var rawEsc=DS.esc;
var GM={'\u2196':'ul','\u2197':'ur','\u2193':'dn','\u2713':'ck','\u2733':'sp'};
function esc(s){return rawEsc(s).replace(/[\u2196\u2197\u2193\u2713\u2733]/g,function(c){return '<span class="sp-gl" data-g="'+GM[c]+'" aria-hidden="true">'+c+'</span>'})}
