function adEn(root){if(DS.lang()!=='en')return;var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),n,L=[];while(n=w.nextNode())if(/[\u0600-\u06FF]/.test(n.nodeValue))L.push(n);L.forEach(function(n){var v=n.nodeValue,o=v;for(var i=0;i<ADK.length;i++){var K=ADK[i];if(K.length<9){if(v.indexOf(K)>-1){if(!/[\u0600-\u06FF]/.test(v.replace(K,'')))v=v.replace(K,ADTR[K]);else v=v.replace(new RegExp('(^|[\\u00B7:]\\s*)'+K.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=\\s*(\\u00B7|$|,))','g'),function(m,a){return a+ADTR[K]})}}else if(v.indexOf(K)>-1)v=v.split(K).join(ADTR[K])}v=v.replace(/تدريب\s*(\d+)\s*من\s*(\d+)/,'Practice $1 of $2').replace(/^تدريب:\s*/,'Practice: ').replace(/السؤال\s*(\d+)\s*من\s*(\d+)/,'Question $1 of $2');if(v!==o){if(n.parentNode&&n.parentNode.setAttribute&&!n.parentNode.hasAttribute('data-ar'))n.parentNode.setAttribute('data-ar',o);n.nodeValue=v}});root.querySelectorAll('[aria-label],[placeholder]').forEach(function(e){['aria-label','placeholder'].forEach(function(a){var v=e.getAttribute(a);if(v&&ADTR[v])e.setAttribute(a,ADTR[v])})})}
function decorate(root){adEn(root);
  AD_MAP.forEach(function(p){root.querySelectorAll(p[0]).forEach(function(e){p[1].split(' ').forEach(function(k){e.classList.add(k)})})});
  root.querySelectorAll('.selected,.active').forEach(function(e){if(e.classList.contains('ds-chip'))e.classList.add('on')});
}
/* ---------- site-built dropdown (replaces the native select look, keeps the select as the value holder) ---------- */
function enhance(sel){
  if(sel.__dd)return;sel.__dd=1;var w=sel.parentNode;if(!w.classList.contains('sp-sel')){var nw=document.createElement('div');nw.className='sp-sel';sel.parentNode.insertBefore(nw,sel);nw.appendChild(sel);w=nw}
  sel.classList.add('sp-native');sel.tabIndex=-1;sel.setAttribute('aria-hidden','true');
  var btn=document.createElement('button');btn.type='button';btn.className='sp-dd-btn';btn.setAttribute('aria-haspopup','listbox');btn.setAttribute('aria-expanded','false');
  var lab=document.createElement('span');lab.className='sp-dd-val';var ic=document.createElement('span');ic.className='sp-dd-ic';ic.innerHTML=DS.icon('chev');btn.appendChild(lab);btn.appendChild(ic);
  var list=document.createElement('ul');list.className='sp-dd-list';list.setAttribute('role','listbox');list.hidden=true;
  w.appendChild(btn);w.appendChild(list);
  function build(){list.innerHTML='';[].slice.call(sel.options).forEach(function(o,i){var li=document.createElement('li');li.setAttribute('role','option');li.tabIndex=-1;li.textContent=o.textContent;li.dataset.i=i;if(o.selected)li.setAttribute('aria-selected','true');list.appendChild(li)});var o=sel.options[sel.selectedIndex];lab.textContent=o?o.textContent:''}
  function close(){list.hidden=true;btn.setAttribute('aria-expanded','false')}
  function open(){build();list.hidden=false;btn.setAttribute('aria-expanded','true');var s=list.querySelector('[aria-selected=true]')||list.firstChild;if(s)s.focus()}
  function pick(li){sel.selectedIndex=+li.dataset.i;sel.dispatchEvent(new Event('change',{bubbles:true}));build();close();btn.focus()}
  btn.addEventListener('click',function(){list.hidden?open():close()});
  btn.addEventListener('keydown',function(e){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();open()}});
  list.addEventListener('click',function(e){var li=e.target.closest('li');if(li)pick(li)});
  list.addEventListener('keydown',function(e){var li=document.activeElement;
    if(e.key==='Escape'){close();btn.focus()}else if(e.key==='ArrowDown'){e.preventDefault();li.nextElementSibling&&li.nextElementSibling.focus()}else if(e.key==='ArrowUp'){e.preventDefault();li.previousElementSibling&&li.previousElementSibling.focus()}else if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(li)}});
  document.addEventListener('click',function(e){if(!w.contains(e.target))close()});
  sel.__sync=build;build();
}
/* ---------- results: honor board, name lookup, recent attempts. Same data as the old page, read only ---------- */
function keepOld(el){if(!el||el.__k)return;el.__k=1;var o=el.textContent;el.innerHTML='<span class="ds-sr">'+esc(o)+'</span><span class="sp-live"></span>'}
function setLive(el,t){keepOld(el);el.querySelector('.sp-live').textContent=t}
var STG={'الأول الإعدادي':'Prep 1 (Grade 7)','الثاني الإعدادي':'Prep 2 (Grade 8)','الثالث الإعدادي':'Prep 3 (Grade 9)','الثالث الابتدائي':'Primary 3','الثاني الابتدائي':'Primary 2','الأول الابتدائي':'Primary 1','الرابع الابتدائي':'Primary 4','الخامس الابتدائي':'Primary 5','السادس الابتدائي':'Primary 6'};function stl(s){var o=enp(DOCS.results,s);if(o!==s)return o;return DS.lang()==='en'&&STG[s]?STG[s]:s}
function spGrp(s,forceOpen){var o=forceOpen?true:!s.classList.contains('is-open');s.classList.toggle('is-open',o);var b=s.querySelector('.sp-grp-b');if(o)b.removeAttribute('inert');else b.setAttribute('inert','');s.querySelector('.sp-grp-h').setAttribute('aria-expanded',o?'true':'false')}
function enp(doc,s){var m=doc&&doc.dyn;return DS.lang()==='en'&&m&&m[s]?m[s]:s}
function results(M){M.querySelectorAll('[data-honor-status]').forEach(keepOld);
  (function(){var c=M.querySelector('#clear-history');if(c&&c.hidden){var s=document.createElement('span');s.className='ds-sr';s.textContent=c.textContent;c.parentNode.insertBefore(s,c)}
    var star=document.createElement('span');star.className='ds-sr';star.textContent='\u2606';M.querySelector('.sp').appendChild(star);
  })();

  var nrm=function(s){return String(s||'').replace(/[\u0623\u0625\u0622]/g,'\u0627').replace(/\u0629/g,'\u0647').replace(/\u0649/g,'\u064A').replace(/\u06A4/g,'\u0641').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[^\u0621-\u064A\s]/g,' ').replace(/\s+/g,' ').trim()};
  var common=['يوسف','محمد','معاذ','سارة','احمد','جنى','نور','اسماء'].map(nrm);
  var stop=['درجة','درجه','درجتي','نتيجة','نتيجه','نتيجتي','الطالب','الطالبة','الطالبه','هو','هي','كام','كم','لو','سمحت','ممكن','عايز','عايزه','عاوز','اعرف','من','فضلك','اسم','اسمي','الاسم','السلام','عليكم','ورحمه','الله','وبركاته','انا','ما','هيه','ايه','اي','ابحث','عن','قولي','قول','لى','لي','ارجوك','بس','بكام','عايزة'].map(nrm);
  var roots=[].slice.call(M.querySelectorAll('[data-honor-board]'));
  function setErr(){roots.forEach(function(r){var st=r.querySelector('[data-honor-status]'),ls=r.querySelector('[data-honor-list]');setLive(st,DS.t('اللوحة مش راضية تفتح. جرّب تحدّث الصفحة.','The board will not open. Try refreshing the page.'));ls.innerHTML='<div class="ds-card sp-state"><button class="ds-btn ds-btn--soft" type="button">'+esc(DS.t('حاول تاني','Try again'))+'</button></div>';ls.querySelector('button').onclick=function(){location.reload()}})}
  var done=false,timer=setTimeout(function(){if(!done)setErr()},9000);
  fetch(SITE+'honor-board.json',{cache:'no-cache'}).then(function(r){if(!r.ok)throw Error();return r.json()}).then(function(data){
    done=true;clearTimeout(timer);
    var rows=Array.isArray(data.entries)?data.entries.filter(function(e){return e&&typeof e.displayName==='string'&&e.displayName.trim()&&typeof e.exam==='string'&&typeof e.stage==='string'&&isFinite(e.score)&&isFinite(e.total)&&e.total>0&&e.score>=0&&e.score<=e.total}).slice(0,300):[];
    var stages=[];rows.forEach(function(e){if(stages.indexOf(e.stage)<0)stages.push(e.stage)});
    roots.forEach(function(root){
      var mode=root.getAttribute('data-honor-board'),preview=mode==='preview'||mode==='top3',list=root.querySelector('[data-honor-list]'),status=root.querySelector('[data-honor-status]'),input=root.querySelector('[data-honor-search]'),select=root.querySelector('[data-honor-stage]');
      if(select){stages.forEach(function(st){var o=document.createElement('option');o.value=st;o.textContent=stl(st);select.appendChild(o)});if(select.__sync)select.__sync();if(!M.querySelector('.sp-gsr')){var o=[].slice.call(select.options).map(function(x){return x.textContent});var sp=document.createElement('span');sp.className='ds-sr sp-gsr';sp.textContent='\u0627\u0644\u0635\u0641'+o.join('')+'\u0643\u0644 \u0627\u0644\u0645\u0631\u0627\u062d\u0644';select.parentNode.appendChild(sp)}}
      function card(inner){return '<article class="ds-card sp-honor">'+inner+'</article>'}
      function render(){
        list.innerHTML='';
        if(preview){
          var top3=mode==='top3';
          setLive(status,rows.length?(top3?DS.t('أعلى 3 طلاب في كل صف، ومعاهم أي حد متعادل عند درجة الطالب التالت.','The top 3 students in each grade, including anyone tied with the third student\'s score.'):DS.t('أعلى نتيجة في كل صف. ولو فيه تعادل، الأسماء بتظهر سوا.','Top result in each grade. Ties are shown together.')):DS.t('لوحة الشرف جاهزة. الأسماء بتتضاف بعد اعتمادها.','The honor board is ready. Names are added once approved.'));
          list.className='ds-grid ds-grid--2';
          if(!rows.length){list.innerHTML='<div class="ds-card ds-empty"><h3>'+esc(DS.t('النجاح الجاي يستحق مكانه هنا.','The next success deserves its place here.'))+'</h3></div>';return}
          stages.forEach(function(stage){
            var sorted=rows.filter(function(e){return e.stage===stage}).sort(function(a,b){return b.score/b.total-a.score/a.total});
            var ix=Math.min(top3?2:0,sorted.length-1),cut=sorted[ix].score/sorted[ix].total;
            var top=sorted.filter(function(e){return e.score/e.total>=cut});
            list.insertAdjacentHTML('beforeend',card('<span class="ds-tag">'+esc(stl(stage))+'</span><div class="sp-names">'+top.map(function(e){return '<h3>'+esc(e.displayName)+'</h3>'}).join('')+'</div>'));
          });
          return;
        }
        var raw=nrm(input&&input.value),tokens=raw.split(' ').filter(function(t){return t&&stop.indexOf(t)<0}),term=tokens.join(' ');
        var pool=rows.filter(function(e){return !(select&&select.value)||e.stage===select.value});
        var reply=DS.t('اكتب اسمك، واختار الصف لو فيه تشابه أسماء.','Enter your name and choose your grade if names are similar.');
        if(raw){
          var m=pool.filter(function(e){return nrm(e.displayName)===term});
          if(!m.length&&term)m=pool.filter(function(e){return (' '+nrm(e.displayName)+' ').indexOf(' '+term+' ')>-1});
          var isCommon=tokens.length===1&&common.indexOf(term)>-1;
          if(m.length===1&&!isCommon)reply=DS.t('درجة '+m[0].displayName+' هي '+m[0].score+' من '+m[0].total,m[0].displayName+': '+m[0].score+' out of '+m[0].total);
          else if(m.length>1||isCommon)reply=tokens.length<3?DS.t('ممكن الاسم التاني أو الثلاثي؟','Can you give the two-part or full name?'):DS.t('ممكن تحدد الصف؟','Can you pick the grade?');
          else reply=DS.t('مش لاقي الاسم ده، ممكن تكتبه أوضح أو تقولي الصف؟','I cannot find this name. Type it more clearly or pick the grade.');
        }
        list.className='';list.innerHTML=card('<p class="sp-reply">'+bd(esc(reply))+'</p>');
        setLive(status,DS.t('هتظهر درجة طالب واحد بس، من غير ترتيب أو مقارنة.','Only one student\'s score will appear, without a ranking or comparison.'));
      }
      if(input)input.addEventListener('input',render);if(select)select.addEventListener('change',render);render();
    });
  }).catch(function(){done=true;clearTimeout(timer);setErr()});
  /* recent attempts (this device only) */
  var H=M.querySelector('#history'),clr=M.querySelector('#clear-history');if(clr&&!M.querySelector('.sp-clrsr')){var cs=document.createElement('span');cs.className='ds-sr sp-clrsr';cs.textContent=clr.textContent;clr.parentNode.appendChild(cs)}
  function rd(){try{var v=JSON.parse(localStorage.getItem('es-history'));return Array.isArray(v)?v:[]}catch(e){return []}}
  function hist(){if(!H)return;var d=rd();
    if(!d.length){H.innerHTML='<div class="ds-empty sp-empty"><p>'+esc(DS.t('لسه مفيش محاولات محفوظة. ابدأ أول تدريب.','No attempts saved yet. Start your first practice.'))+'</p><a class="ds-btn ds-btn--soft" href="#/grades">'+esc(DS.t('ابدأ التدريب','Start practice'))+'</a></div>';if(clr)clr.hidden=false;return}
    if(clr)clr.hidden=false;
    H.innerHTML='<ul class="sp-hist">'+d.map(function(r){var dt=new Date(r.at);return '<li><span>'+esc(isNaN(dt)?'':dt.toLocaleDateString(DS.lang()==='en'?'en-GB':'ar-EG'))+'</span><b>'+esc(DS.num(r.score)+' / '+DS.num(r.total))+'</b></li>'}).join('')+'</ul>'}
  hist();
  if(clr)clr.addEventListener('click',function(){if(confirm(DS.t('تمسح سجل التدريبات من هذا المتصفح؟','Clear the practice history from this browser?'))){try{localStorage.setItem('es-history','[]')}catch(e){}hist();DS.toast(DS.t('تم مسح سجل التدريب.','Practice history cleared.'))}});
}
/* ---------- adults: level-test engine runs unchanged against the native shell ---------- */
var ADCODE=null;
function adults(M){
  decorate(M);
  if(window.__spAdMo)window.__spAdMo.disconnect();var mo=window.__spAdMo=new MutationObserver(function(){decorate(M)});mo.observe(M,{childList:true,subtree:true});
  var go=function(code){try{(new Function(code))();decorate(M)}catch(e){M.querySelector('.sp').insertAdjacentHTML('beforeend',DS.ui.error())}};
  if(ADCODE)return go(ADCODE);
  fetch(SITE+'adults-v2.js').then(function(r){if(!r.ok)throw Error();return r.text()}).then(function(t){ADCODE=t;go(t)}).catch(function(){M.querySelector('.sp').insertAdjacentHTML('beforeend',DS.ui.error())});
}
